import React, { memo } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Vibration, Linking } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { Image } from 'expo-image';
import { Ionicons, FontAwesome } from '@expo/vector-icons';
import { ProfileTheme } from '../../constants/ProfileTheme';
import VerifiedBadge from './VerifiedBadge';
import DeveloperBadge from './DeveloperBadge';

interface SocialLinks {
    instagram?: string;
    twitter?: string;
    facebook?: string;
}

interface UserInfoProps {
    name: string;
    username: string;
    bio?: string;
    location: string;
    team: string; // "Favorite Team"
    isVerified?: boolean;
    isDeveloper?: boolean;
    onBioLongPress?: () => void;
    onNameLongPress?: () => void;
    clubLogo?: string; // Club logo URL
    onEditPress?: () => void;
    socials?: SocialLinks; // روابط السوشيال ميديا
}

const UserInfo = memo(function UserInfo({
    name,
    username,
    bio = 'عاشق لكره القدم', // Default fallback
    location,
    team,
    isVerified = false,
    isDeveloper = false,
    onBioLongPress,
    onNameLongPress,
    clubLogo,
    onEditPress,
    socials,
}: UserInfoProps) {

    const handleSocialPress = (url: string) => {
        Linking.openURL(url).catch(err => console.error("Couldn't load page", err));
    };

    // تحقق من وجود أي رابط سوشيال ميديا
    const hasSocials = socials && (socials.instagram || socials.twitter || socials.facebook);
    return (
        <View style={styles.container}>
            {/* 1. Name & Badges */}
            <TouchableOpacity
                onLongPress={() => {
                    if (onNameLongPress) {
                        Vibration.vibrate(50);
                        onNameLongPress();
                    }
                }}
                activeOpacity={0.7}
            >
                <View style={styles.nameRow}>
                    <Text style={styles.name}>{name}</Text>
                    {isDeveloper && (
                        <View style={styles.badgeContainer}>
                            <DeveloperBadge size={24} />
                        </View>
                    )}
                    {isVerified && !isDeveloper && (
                        <View style={styles.badgeContainer}>
                            <VerifiedBadge size={24} />
                        </View>
                    )}

                    {/* Edit Pen Icon */}
                    <TouchableOpacity
                        onPress={onEditPress}
                        style={styles.editButton}
                        activeOpacity={0.7}
                    >
                        <Ionicons name="pencil" size={18} color={ProfileTheme.colors.neonBlue} />
                    </TouchableOpacity>
                </View>
            </TouchableOpacity>

            {/* Username */}
            <Text style={styles.username}>@{username}</Text>

            {/* 2. Location & Favorite Team Row (Merged) */}
            <View style={styles.detailsRow}>
                <View style={styles.detailItem}>
                    <Ionicons name="location-outline" size={16} color={ProfileTheme.colors.textSecondary} />
                    <Text style={styles.detailText}>{location || 'مصر'}</Text>
                </View>
                <View style={styles.detailItem}>
                    {clubLogo ? (
                        <Image
                            source={{ uri: clubLogo }}
                            style={styles.clubLogo}
                            contentFit="contain"
                            cachePolicy="memory-disk"
                        />
                    ) : (
                        <Ionicons name="football-outline" size={16} color={ProfileTheme.colors.neonGreen} />
                    )}
                    <Text style={styles.detailText}>{team || 'اختر ناديك'}</Text>
                </View>
            </View>

            {/* 3. Bio with Social Links (Combined) */}
            <View style={styles.bioSection}>
                <TouchableOpacity
                    onLongPress={() => {
                        if (onBioLongPress) {
                            Vibration.vibrate(50); // Haptic feedback
                            onBioLongPress();
                        }
                    }}
                    activeOpacity={0.7}
                    style={styles.bioContainer}
                >
                    <Text style={styles.bio}>{bio || 'عاشق لكره القدم'}</Text>
                </TouchableOpacity>

                {/* Social Links - تظهر بجانب البايو */}
                {hasSocials && (
                    <View style={styles.socialRow}>
                        {socials?.instagram && (
                            <TouchableOpacity onPress={() => handleSocialPress(socials.instagram!)} style={styles.socialIcon}>
                                <LinearGradient
                                    colors={['#833AB4', '#FD1D1D', '#FCAF45']}
                                    style={styles.socialGradient}
                                >
                                    <FontAwesome name="instagram" size={16} color="white" />
                                </LinearGradient>
                            </TouchableOpacity>
                        )}

                        {socials?.twitter && (
                            <TouchableOpacity onPress={() => handleSocialPress(socials.twitter!)} style={styles.socialIcon}>
                                <View style={[styles.socialGradient, { backgroundColor: '#000' }]}>
                                    <FontAwesome name="twitter" size={16} color="#1DA1F2" />
                                </View>
                            </TouchableOpacity>
                        )}

                        {socials?.facebook && (
                            <TouchableOpacity onPress={() => handleSocialPress(socials.facebook!)} style={styles.socialIcon}>
                                <View style={[styles.socialGradient, { backgroundColor: '#1877F2' }]}>
                                    <FontAwesome name="facebook" size={16} color="white" />
                                </View>
                            </TouchableOpacity>
                        )}
                    </View>
                )}
            </View>
        </View >
    );
});

export default UserInfo;

const styles = StyleSheet.create({
    container: {
        paddingHorizontal: 20,
        marginBottom: 20,
        alignItems: 'center',
    },
    nameRow: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 8,
        marginBottom: 4,
    },
    name: {
        fontSize: 28,
        fontWeight: 'bold',
        color: ProfileTheme.colors.textPrimary,
        textShadowColor: ProfileTheme.colors.neonBlue,
        textShadowOffset: { width: 0, height: 0 },
        textShadowRadius: 10,
    },
    badgeContainer: {
        justifyContent: 'center',
        alignItems: 'center',
    },
    username: {
        fontSize: 16,
        color: ProfileTheme.colors.textSecondary,
        marginBottom: 16,
        textAlign: 'center',
        letterSpacing: 1,
    },
    detailsRow: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        marginBottom: 16,
        gap: 12,
    },
    detailItem: {
        flexDirection: 'row',
        alignItems: 'center',
        gap: 6,
        backgroundColor: 'rgba(255,255,255,0.05)',
        paddingHorizontal: 12,
        paddingVertical: 8,
        borderRadius: 12,
        borderWidth: 1,
        borderColor: 'rgba(255,255,255,0.1)',
    },
    detailText: {
        color: ProfileTheme.colors.textSecondary,
        fontSize: 14,
        fontWeight: '500',
    },
    clubLogo: {
        width: 16,
        height: 16,
    },
    bioSection: {
        width: '100%',
        alignItems: 'center',
        marginTop: 8,
    },
    bioContainer: {
        alignItems: 'center',
        padding: 5,
        marginBottom: 12,
    },
    bio: {
        fontSize: 16,
        color: '#DDD',
        lineHeight: 24,
        textAlign: 'center',
        textShadowColor: 'rgba(0,0,0,0.5)',
        textShadowOffset: { width: 1, height: 1 },
        textShadowRadius: 2,
        maxWidth: '90%',
    },
    bioHint: {
        fontSize: 10,
        color: 'rgba(255,255,255,0.3)',
        marginTop: 4,
    },
    editButton: {
        backgroundColor: 'rgba(255,255,255,0.1)',
        padding: 6,
        borderRadius: 20,
        marginLeft: 8,
    },
    socialRow: {
        flexDirection: 'row',
        gap: 12,
        justifyContent: 'center',
        alignItems: 'center',
        flexWrap: 'wrap',
    },
    socialIcon: {
        width: 32,
        height: 32,
        borderRadius: 16,
        overflow: 'hidden',
    },
    socialGradient: {
        width: '100%',
        height: '100%',
        justifyContent: 'center',
        alignItems: 'center',
    }
});
